'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var abs = require( '@stdlib/math/base/special/abs' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var logcdf = factory( 0.0, 1.0 );
	t.strictEqual( typeof logcdf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var cdf;
	var y;

	cdf = factory( 1, 1.0 );
	y = cdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	cdf = factory( NaN, 1.0 );
	y = cdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	cdf = factory( 1, NaN );
	y = cdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	cdf = factory( NaN, NaN );
	y = cdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	cdf = factory( NaN, NaN );
	y = cdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a finite `k` and `lambda`, the function returns a function which returns `0` when provided `+infinity` for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 2, 1.0 );
	y = logcdf( PINF );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'if provided a finite `k` and `lambda`, the function returns a function which returns `-Infinity` when provided `-infinity` for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 2, 1.0 );
	y = logcdf( NINF );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'if provided a negative `lambda`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 2, -1.0 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 0.0, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( PINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a negative `k`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( -1.0, 0.5 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, 1.0 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, PINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NaN );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the logcdf for `x` given rate parameter `lambda` and shape parameter `k`', function test( t ) {
	var expected;
	var lambda;
	var logcdf;
	var delta;
	var tol;
	var i;
	var k;
	var x;
	var y;

	expected = data.expected;
	x = data.x;
	k = data.k;
	lambda = data.lambda;
	for ( i = 0; i < x.length; i++ ) {
		logcdf = factory( k[i], lambda[i] );
		y = logcdf( x[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', k:'+k[i]+', lambda: '+lambda[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			delta = abs( y - expected[ i ] );
			tol = 450.0 * EPS * abs( expected[ i ] );
			t.ok( delta<=tol, 'within tolerance. x: '+x[ i ]+'. k: '+k[i]+'. lambda: '+lambda[i]+'. y: '+y+'. E: '+expected[ i ]+'. Δ: '+delta+'. tol: '+tol+'.' );
		}
	}
	t.end();
});
